import sys
import math

def precompute_powerful_numbers(max_n):
    powerful = set()
    # Add powers of two up to max_n
    d = 0
    while True:
        power = 2 ** d
        if power > max_n:
            break
        powerful.add(power)
        d += 1
    # Add factorials up to max_n
    d = 0
    while True:
        fact = 1
        for i in range(1, d + 1):
            fact *= i
            if fact > max_n:
                break
        if fact > max_n:
            break
        powerful.add(fact)
        d += 1
    return sorted(powerful)

def solve():
    input_lines = sys.stdin.read().splitlines()
    t = int(input_lines[0])
    test_cases = list(map(int, input_lines[1:t+1]))

    max_n = max(test_cases) if test_cases else 0
    powerful_numbers = precompute_powerful_numbers(max_n)

    for n in test_cases:
        if n in powerful_numbers:
            print(1)
            continue

        # Check if n can be represented as sum of distinct powerful numbers
        # We'll use a greedy approach with the largest powerful numbers first
        # This is not guaranteed to give the minimal k, but it's a heuristic
        # For exact minimal k, we need a more sophisticated approach
        # Given the constraints, we'll use a dynamic programming approach with a limited set of powerful numbers

        # Since n can be up to 1e12, we need to limit the powerful numbers to those <= n
        powerful_up_to_n = [num for num in powerful_numbers if num <= n]
        m = len(powerful_up_to_n)

        # Initialize DP: dp[i] = minimal k to form sum i
        # We'll use a dictionary to store only reachable sums
        dp = {0: 0}
        for num in powerful_up_to_n:
            new_dp = {}
            for s in dp:
                new_sum = s + num
                if new_sum <= n:
                    if new_sum not in new_dp or dp[s] + 1 < new_dp.get(new_sum, float('inf')):
                        new_dp[new_sum] = dp[s] + 1
            dp.update(new_dp)
        if n in dp:
            print(dp[n])
        else:
            print(-1)

solve()
